(() => {
  'use strict';
  const D=window.PARTY_DATA,root=document.getElementById('party-app'),KEY='ppm_spotlight6_module2a_v1';
  const KEYS=[KEY,'ppm_spotlight6_module1_v2','ppm_spotlight6_skills_v2','ppm_spotlight6_sidequests_v1'];
  const fresh=()=>({stage:null,tab:'learn',answers:{},checks:{},tries:{},hints:{},reveals:{},done:{},fields:{},open:{},extra:{},clock:{h:3,m:30},date:{d:17,m:7},guests:[]});
  let state=fresh(),storageOK=true,teacher=false,resetModal=false,lastFocus=null,toastTimer=null,memTimer=null;
  try{const x=JSON.parse(localStorage.getItem(KEY)||'{}');state={...state,...x};if(!D.stages.some(s=>s.id===state.stage))state.stage=null;}catch{storageOK=false;}
  const esc=(x='')=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const norm=x=>String(x||'').toLowerCase().trim().replace(/[’‘]/g,"'").replace(/[-–—]/g,' ').replace(/[.,!?;:]+$/g,'').replace(/\s+/g,' ').replace(/^(it's|it is) /,'');
  const shuffle=a=>{const r=[...a];for(let i=r.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];}return r;};
  const save=()=>{try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storageOK=false;}};
  const field=(k,def='')=>state.fields[k]??def;
  const completed=()=>D.stages.filter(s=>state.done[s.id]).length;
  const stop=()=>window.speechSynthesis?.cancel();
  function toast(s){document.querySelector('.toast')?.remove();clearTimeout(toastTimer);const n=document.createElement('div');n.className='toast';n.setAttribute('role','status');n.textContent=s;document.body.append(n);toastTimer=setTimeout(()=>n.remove(),3500);}
  function go(id,tab='learn'){clearTimeout(memTimer);stop();state.stage=id;state.tab=tab;save();render();window.scrollTo(0,0);document.querySelector('#stage-title,#home-title')?.focus({preventScroll:true});}
  function speak(text){if(!window.speechSynthesis){toast('Озвучка недоступна. Прочитай фразу с преподавателем.');return;}stop();const u=new SpeechSynthesisUtterance(text);u.lang='en-GB';u.rate=.85;u.voice=speechSynthesis.getVoices().find(v=>v.lang==='en-GB')||null;u.onerror=()=>toast('Озвучка недоступна. Попроси преподавателя прочитать текст.');speechSynthesis.speak(u);}
  const note=(title,body,yellow=false)=>`<div class="callout ${yellow?'yellow':''}"><b>${title}</b>${body}</div>`;
  const detail=(title,body)=>`<details data-detail="${esc(title)}" ${state.open['detail:'+title]?'open':''}><summary>${title}</summary>${body}</details>`;
  const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const input=(k,label,def='',type='text')=>`<label class="field">${label}<input type="${type}" data-field="${esc(k)}" value="${esc(field(k,def))}" autocomplete="off"></label>`;
  const area=(k,label,placeholder='')=>`<label class="field">${label}<textarea data-field="${esc(k)}" placeholder="${esc(placeholder)}">${esc(field(k))}</textarea></label>`;
  const checkboxes=(prefix,labels)=>`<div class="checklist">${labels.map((s,i)=>`<label><input type="checkbox" data-field="${prefix}${i}" ${field(prefix+i)?'checked':''}>${s}</label>`).join('')}</div>`;
  const keks=s=>`<aside class="keks-note"><img src="./assets/keks/keks-skeptical.webp" alt="Кекс помогает заметить языковую деталь"><p><strong>KEKS SAYS</strong>${s}</p></aside>`;
  const bridge=(student,tutor)=>`<div class="aftertask"><div class="turn"><b>STUDENT TURN · ТВОЯ ОЧЕРЕДЬ</b><p>${student}</p></div><div class="turn"><b>ASK YOUR TUTOR · ПОМЕНЯЙТЕСЬ РОЛЯМИ</b><p>${tutor}</p></div></div>`;
  function render(){
    const focused=document.activeElement;
    const bookmark=focused&&root.contains(focused)?Object.entries(focused.dataset).find(([k])=>k!=='field'):null;
    const st=D.stages.find(x=>x.id===state.stage);
    root.innerHTML=`${!storageOK?'<div class="storage-warning" role="status">Браузер не разрешает сохранение. Пока вкладка открыта, можно заниматься; после закрытия прогресс может исчезнуть.</div>':''}<header class="top"><a class="brand" href="./index.html">VICTORIA / ENGLISH STUDIO<small>SPOTLIGHT 6 · MODULE 2a</small></a><nav class="topnav" aria-label="Инструменты"><a class="btn" href="./index.html">MODULE 1</a><button data-home>MODULE 2 MAP</button><button data-teacher>TUTOR NOTES</button><button data-reset>NEW STUDENT / RESET ALL</button></nav></header><div class="progress" role="progressbar" aria-label="Прогресс раздела 2a" aria-valuemin="0" aria-valuemax="12" aria-valuenow="${completed()}"><i style="width:${completed()/12*100}%"></i></div><main id="main" class="wrap">${st?stageView(st):home()}</main><div class="modal" ${teacher||resetModal?'':'hidden'}><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="close" data-close aria-label="Закрыть окно">×</button>${resetModal?resetView():teacherView()}</section></div>`;
    bind();if(teacher||resetModal)document.querySelector('.dialog .close')?.focus();else if(bookmark){const [key,value]=bookmark;[...root.querySelectorAll('button,a')].find(el=>el.dataset[key]===value)?.focus({preventScroll:true});}
  }
  function home(){return `<section class="hero"><div><div class="kicker">Happy times · pages 16–17 · A1 → A2</div><h1 id="home-title" tabindex="-1">PARTY<br><span>BUREAU.</span></h1><p>У Кекса четыре приглашения и слишком много планов. Помоги разобраться с датами и временем — и устрой собственную вечеринку.</p><p class="small">Русские объяснения · игры без таймера · один ученик + преподаватель</p><div class="actions"><button class="primary" data-go="${D.stages.find(s=>!state.done[s.id])?.id||'inbox'}">${completed()?'CONTINUE · ПРОДОЛЖИТЬ':'OPEN THE FILES →'}</button><button data-go="time">ПОИГРАТЬ С ЧАСАМИ</button></div><p class="small">${completed()} / 12 этапов завершено. Все этапы открыты — можно выбрать нужный.</p></div><div class="poster"><div class="ticket"><div class="kicker">You’re invited</div><strong>GOOD<br>TIMES<br>AHEAD.</strong><p>DATE? &nbsp; TIME? &nbsp; PLACE?<br>Let’s make a plan.</p></div><img src="./assets/keks/keks-sitting.webp" alt="Кекс — помощник в бюро приглашений"><div class="stamp">YOUR MISSION<br><b>Создать приглашение, по которому гость точно найдёт вечеринку.</b></div></div></section><section><div class="sectionhead"><div><div class="kicker">Core route · основной маршрут</div><h2>Большая тема.<br>Небольшие шаги.</h2></div><p>План на 3 занятия по 45–60 минут. Для ученика с пробелами разбей на 4–5 занятий. Сначала «Разберёмся», затем «Играем», в конце «Про тебя».</p></div><div class="route-grid"><div class="route"><small>LESSON 1 / 01–04</small><h3>Разобраться в календаре</h3><p>Приглашения → дни → месяцы → порядковые числа. Итог: узнать дату в приглашении.</p><button data-go="inbox">Начать занятие 1</button></div><div class="route"><small>LESSON 2 / 05–07</small><h3>Назначить встречу</h3><p>Даты → часы → at / on / in. Итог: назвать дату и время встречи.</p><button data-go="dates">Начать занятие 2</button></div><div class="route"><small>LESSON 3 / 08–12</small><h3>Пригласить по-настоящему</h3><p>Голосовое сообщение → интервью → своё приглашение → финальное дело.</p><button data-go="radio">Начать занятие 3</button></div></div><div class="sectionhead"><div><div class="kicker">Choose a file</div><h2>Карта раздела 2a</h2></div><p class="small">Это начало Module 2: добавлен весь материал двух присланных страниц 2a. Следующие разделы модуля добавим по новым страницам.</p></div><div class="map">${D.stages.map(s=>`<button data-go="${s.id}"><span class="num">${String(s.no).padStart(2,'0')} ${state.done[s.id]?'✓ ЗАВЕРШЕНО':''}</span><b>${s.title}</b><small>${s.ru}</small></button>`).join('')}</div></section>${footer()}`;}
  const footer=()=>`<footer class="footer">VICTORIA · Interactive English Website Studio · Учебный материал по темам Spotlight 6, 2a. Новые игры и диалоги. Прогресс хранится только в этом браузере. Озвучка — необязательный голос браузера; преподаватель может читать вместо неё.</footer>`;
  function stageView(st){return `<div class="lesson-layout"><aside class="rail"><button class="railhome" data-home>← MODULE 2 MAP</button><nav aria-label="Этапы урока">${D.stages.map(s=>`<button class="${st.id===s.id?'active':''}" data-go="${s.id}" ${st.id===s.id?'aria-current="step"':''}>${String(s.no).padStart(2,'0')} ${s.ru} ${state.done[s.id]?'✓':''}</button>`).join('')}</nav><div class="mini"><b>${completed()} / 12 FILES COMPLETE</b><p>Ошибки помогают найти трудное место. Подсказки можно открывать сколько угодно.</p></div></aside><div><section class="stage-heading"><div><div class="kicker">${st.no<5?'Lesson 1':st.no<8?'Lesson 2':'Lesson 3'} · Happy times</div><h1 id="stage-title" tabindex="-1">${st.title}</h1><p>${st.desc}</p></div><span class="count">${String(st.no).padStart(2,'0')}</span></section><nav class="tabs" aria-label="Режим этапа">${[['learn','01 · РАЗБЕРЁМСЯ'],['play','02 · ИГРАЕМ'],['use','03 · ПРО ТЕБЯ']].map(([id,label])=>`<button data-tab="${id}" class="${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav><section class="panel">${state.tab==='learn'?learn(st.id):state.tab==='play'?play(st.id):use(st.id)}</section><div class="stage-footer"><button data-prev ${st.no===1?'disabled':''}>← Назад</button><span class="status">${state.done[st.id]?'✓ Этап завершён':st.quiz?'Этап засчитается, когда все ответы в Core Check верны.':'Открытый этап: проверь результат с преподавателем.'}</span><button class="primary" data-next>${st.no===12?'К карте →':'Следующий этап →'}</button></div>${footer()}</div></div>`;}
  function flash(words,prefix){return `<p class="small">Нажми на слово, чтобы открыть перевод. Нажми ещё раз, чтобы скрыть. Значок озвучки читает слово голосом браузера.</p><div class="vocab">${words.map((w,i)=>`<div><button class="word" data-flash="${prefix+i}" aria-expanded="${!!state.open[prefix+i]}"><strong lang="en">${w[0]}</strong><small>${w[2]||''}</small>${prefix==='day'?`<small>Коротко: ${w[3]}</small>`:''}<span>${state.open[prefix+i]?w[1]:'Открыть перевод +'}</span></button><button class="quiet" data-say="${esc(w[0])}" aria-label="Прослушать ${esc(w[0])}">▷ Listen</button></div>`).join('')}</div>`;}
  function learn(id){
    if(id==='inbox')return `<h2>Четыре карточки. Четыре события.</h2><p>Сначала посмотри на заголовки. Какие приглашения на день рождения? Какое — на окончание университета? Не переводи каждое слово: начни с общей мысли.</p>${note('Слова для первого чтения',`<p><b>birthday party</b> — вечеринка на день рождения; <b>invitation</b> — приглашение; <b>graduation</b> — окончание учебного заведения; <b>address</b> — адрес; <b>celebrate</b> — праздновать; <b>join us</b> — присоединиться к нам; <b>occasion</b> — повод/событие; <b>drinks, dinner & dessert</b> — напитки, ужин и десерт.</p><p><b>A party is brewing</b> — «назревает вечеринка»: игра слов с brewing («заваривать», как ведьмино зелье). <b>Trick or treat</b> — «сладость или гадость», традиционная хэллоуинская фраза. <b>You are invited</b> = тебя приглашают. <b>Please come</b> = пожалуйста, приходи. <b>Hope to see you there!</b> = надеюсь увидеть тебя там! <b>See you then!</b> = до встречи в назначенное время. <b>Next week</b> = на следующей неделе.</p>`)}<div class="invitations">${D.invitations.map(c=>`<article class="invite"><span class="letter">FILE ${c.id}</span><h3 lang="en">${c.title}</h3><p lang="en">${esc(c.text).replace(/\n/g,'<br>')}</p>${detail('Помоги понять по-русски',`<p>${c.ru}</p>`)}</article>`).join('')}</div>${detail('Как найти ответ, даже если текст кажется сложным',`<ol><li><b>Who is inviting?</b> Кто зовёт? Ищи подпись или From.</li><li><b>Who is the guest?</b> Кого зовут? Ищи Dear, Hey или To.</li><li><b>What is the occasion?</b> Что празднуют? Birthday, Halloween, graduation.</li><li><b>When?</b> Когда? Ищи дату, день и время после on / at.</li><li><b>Where?</b> Где? Ищи address, house, название улицы и номер дома.</li></ol><p>В приглашениях может не быть всей информации. В C имя конкретного гостя не указано — его не нужно придумывать.</p>`)}${detail('Шифр коротких слов: Sat, Dec, Rd., St., pm, &',table(['Запись','Полная форма','Что значит'],[['Sat','Saturday','суббота'],['Dec','December','декабрь'],['Rd.','Road','название улицы/дороги в адресе'],['St.','Street','улица'],['am','ante meridiem','до полудня: 00:00–11:59'],['pm','post meridiem','после полудня: 12:00–23:59'],['&','and','и; это символ, а не сокращённое слово']])+`<p>Для письма Клэр пригодятся <b>Sun = Sunday</b> и <b>Sept = September</b> (также встречается Sep). Точка в сокращениях зависит от стиля. <b>17:30</b> и <b>5:30 pm</b> — одно время.</p>`)}${keks('Сначала найди имя, дату и время. Остальные слова разберём постепенно.')}`;
    if(id==='days')return `<h2>Неделя — семь дней, всегда в одном порядке.</h2>${note('Сначала заметим',`<p class="example" lang="en">The party is <mark>on Saturday</mark>.<br>We have PE lessons <mark>on Monday</mark>.</p><p>Что стоит перед днём недели? <b>On</b>. Названия дней пишем с <b>заглавной буквы</b>.</p>`)}${flash(D.days,'day')}${detail('Как не путать Tuesday и Thursday',`<p><b>Tuesday</b> — вторник; начинается с /tj/ или /tʃ/ в разных вариантах речи. <b>Thursday</b> — четверг, начинается с /θ/: кончик языка чуть между зубами, мягко выдохни. Это не обычный русский «с» или «т».</p><p><b>Wednesday</b> пишется длинно, но обычно звучит /ˈwenz.deɪ/: буква d не слышна. В каждом дне есть часть <b>day</b> — «день».</p>`)}${table(['Вопрос','Ответ','Смысл'],[["What’s your favourite day of the week?","It’s Friday.",'Какой твой любимый день недели? — Пятница.'],['Why?','I have music lessons on Friday.','Почему? — У меня уроки музыки по пятницам.'],['Mine is Sunday.','Mine = my favourite day.','А мой — воскресенье.']])}<p><b>Before</b> — до, <b>after</b> — после. The day after Monday is Tuesday.</p>`;
    if(id==='months')return `<h2>12 месяцев. 4 сезона.</h2><p>Нажми на месяцы, затем закрой переводы и назови их по памяти. В игре соберём календарь.</p>${flash(D.months,'month')}${table(['Сезон','Перевод','Месяцы'],[['winter /ˈwɪn.tə/','зима','December · January · February'],['spring /sprɪŋ/','весна','March · April · May'],['summer /ˈsʌm.ə/','лето','June · July · August'],['autumn /ˈɔː.təm/','осень','September · October · November']])}${note('Обрати внимание',`<p>Месяцы пишем с заглавной: <b>September</b>. Сезоны обычно с маленькой: <b>autumn</b>. В autumn последняя <b>n</b> не произносится. <b>Fall</b> — американский вариант слова autumn.</p><p>Это привычная календарная модель для России и Великобритании. В Южном полушарии сезоны приходятся на другие месяцы.</p>`)}${detail('Произношение и полезные фразы',`<p>В <b>July</b> ударение на второй слог; в <b>September, October, November, December</b> — тоже на второй. В длинном слове не нужно придавать одинаковую силу каждому слогу.</p><p class="example">My birthday is <mark>in May</mark>.<br>I like parties <mark>in summer</mark>.</p><p>Пока назван только месяц или сезон — используем <b>in</b>. Конкретную дату научимся оформлять отдельно.</p>`)}${keks('June — июнь. July — июль. Разница в одной букве, но это целый месяц!')}`;
    if(id==='ordinals')return `<h2>Сколько? Или который по счёту?</h2>${note('Сравни две ситуации',`<p class="example"><b>three</b> balloons — три шарика<br>the <b>third</b> balloon — третий шарик</p><p><b>Three</b> отвечает «сколько?». <b>Third</b> отвечает «который по порядку?». Дата — тоже номер дня в месяце, поэтому для неё нужны порядковые числительные.</p>`)}<div class="flow"><span>four → fourth → 4th</span><span>six → sixth → 6th</span><span>ten → tenth → 10th</span></div><h3>Правило с тремя особенными словами</h3><p>Чаще всего добавляем <b>-th</b>. Но <b>one → first (1st)</b>, <b>two → second (2nd)</b>, <b>three → third (3rd)</b> нужно запомнить отдельно.</p>${detail('Ещё несколько изменений в написании — с объяснениями',table(['Число','Порядковое','Что меняется'],[['five','fifth','ve → f перед th'],['eight','eighth','не добавляем вторую t'],['nine','ninth','убираем e'],['twelve','twelfth','ve → f перед th'],['twenty','twentieth','y → ie перед th'],['thirty','thirtieth','y → ie перед th']]))}${detail('Как выбрать st / nd / rd / th у большого числа',`<p>Посмотри на последние <b>две цифры</b>. <b>11, 12, 13 → всегда th</b>: 11th, 12th, 13th. В остальных случаях последняя цифра 1 → st, 2 → nd, 3 → rd, остальные → th.</p><p>21st, 22nd, 23rd, 24th … 30th, 31st. В составном слове меняется только последняя часть: <b>twenty-one → twenty-first</b>. На письме между словами — дефис.</p>`)}${detail('Полная фабрика: от 1st до 31st',table(['Запись','Словом','Перевод','Прослушать'],D.ordinalWords.map((w,i)=>[D.ordinal(i+1),w,D.ordinalRu[i],`<button class="quiet" data-say="${w}">▷ ${D.ordinal(i+1)}</button>`])))}${detail('Как произнести -th и -st',`<p>Для <b>/θ/</b> в fourth, fifth, sixth кончик языка слегка между зубами. Не добавляй отдельное «эс» в конце. В first конец /st/, в second /nd/, в third /d/. Можно сначала медленно прочитать основу, затем соединить окончание.</p>`)}${note('Не только даты',`<p class="example">the <b>6th form</b> — шестой класс<br>the <b>1st of June</b> — первое июня<br>my <b>12th birthday</b> — мой двенадцатый день рождения</p><p>Перед my / your отдельное the не ставим: <b>my twelfth birthday</b>.</p>`)}`;
    if(id==='dates')return `<h2>Пишем коротко. Произносим полностью.</h2>${note('Разберём 17/08',`<p class="example">17/08 → 17 August<br>It’s <mark>the seventeenth of August</mark>.</p><p>В британском формате сначала <b>день</b>, затем <b>месяц</b>. 17 — семнадцатый день, 08 — восьмой месяц, August. Читаем по формуле <b>the + порядковое число + of + месяц</b>.</p>`)}${dateExplorer()}${table(['Вопрос','Модель ответа','Перевод'],[["What’s the date today?","It’s the seventeenth of August.",'Какое сегодня число? — 17 августа.'],['What was the date yesterday?','It was the sixteenth of August.','Какое число было вчера? — 16 августа.'],['When’s your birthday?','It’s on the fifth of May.','Когда твой день рождения? — 5 мая.']])}${detail('Today / yesterday и переход через границу месяца',`<p><b>Today</b> — сегодня: <b>It is / It’s</b>. <b>Yesterday</b> — вчера: <b>It was</b>. На 17 августа вчера — 16 августа. На 1 января вчера — <b>31 декабря</b>, а не «0 января».</p><p>Если сегодня 1 марта, вчера — 28 февраля, а в високосном году 29 февраля. Год нужен, чтобы выбрать между этими вариантами.</p>`)}${detail('Дата на карточке и дата в речи — не одно и то же',`<p>На приглашении можно написать <b>Sun 4 Sept</b>. В речи: <b>on Sunday, the fourth of September</b>. Варианты <b>4 September</b> и <b>September 4</b> используются на письме; запись June 12th в C тоже обозначает 12 июня.</p><p><b>What day is it?</b> — какой день недели? <b>What’s the date?</b> — какое число? Это разные вопросы.</p>`)}`;
    if(id==='time')return `<h2>Часы, которые можно понять.</h2><p>Передвигай ползунки. Короткая чёрная стрелка показывает часы, длинная синяя — минуты. Между цифрами 5 минут: 1 = 5, 2 = 10, 3 = 15 и так далее.</p>${clockExplorer()}${note('Сначала самый простой способ',`<p class="example">3:30 → <b>three thirty</b><br>8:10 → <b>eight ten</b><br>5:00 → <b>five o’clock</b></p><p>Прочитай сначала часы, потом минуты — это нормальный английский. Для 8:05: <b>eight oh five</b>. Для целого часа можно добавить <b>o’clock</b>. «Three o’clock thirty» говорить не нужно.</p>`)}${detail('PAST: минуты прошли после текущего часа',`<p>С 01-й до 30-й минуты включительно можно сказать <b>минуты + past + текущий час</b>. Past здесь = после.</p><p class="example">3:10 → ten past three<br>3:15 → (a) quarter past three<br>3:30 → half past three</p><p><b>A quarter</b> — четверть часа, то есть 15 минут. <b>Half</b> — половина часа, 30 минут. Русское «половина четвёртого» = <b>half past three</b>, потому что по-английски называем час, который уже прошёл.</p>`)}${detail('TO: сколько минут осталось ДО следующего часа',`<ol><li>Возьми минуты на часах: 9:<b>35</b>.</li><li>Вычти их из 60: 60 − 35 = <b>25</b>.</li><li>Возьми <b>следующий</b> час: после 9 идёт <b>10</b>.</li><li>Соедини: <b>twenty-five to ten</b>.</li></ol><p class="example">3:45 → (a) quarter to four<br>2:55 → five to three<br>12:45 → (a) quarter to one</p><p>Для минут 31–59 используем <b>to + следующий час</b>. Для 12 следующим будет 1. В учебной игре минуты идут с шагом 5; если число минут не кратно 5, часто добавляют minutes: <b>seven minutes past two</b>.</p>`)}${detail('AM / PM без путаницы: 12:00 — особый случай',table(['Запись','24-часовой формат','Смысл'],[['5:45 am','05:45','утро'],['5:45 pm','17:45','вечер'],['12:00 am','00:00','midnight — полночь'],['12:00 pm','12:00','noon — полдень']])+`<p>AM — от полуночи до полудня; PM — от полудня до полуночи. Для часов 1–11 в PM прибавляем 12. Для 12 PM не прибавляем: это 12:00. Чтобы избежать путаницы, можно сказать <b>noon</b> или <b>midnight</b>.</p>`)}${note('Вежливый мини-диалог',`<p class="example">A: Excuse me, what time is it, please?<br>B: It’s half past three. / It’s three thirty.<br>A: Thank you.</p><p>Excuse me — «извините» для привлечения внимания. Не надо дословно переводить русское «сколько времени?» как How much time?</p>`)}${keks('Past — после этого часа. To — до следующего. Стрелки подскажут, какой час назвать.')}`;
    if(id==='preps')return `<h2>Три маленьких слова организуют время.</h2>${note('Сначала найди закономерность',`<p class="example">The party is <mark>on Sunday</mark>.<br>It starts <mark>at 5:45 pm</mark>.<br>My birthday is <mark>in September</mark>.</p><p>В какой фразе точное время? Где один день? Где целый месяц? Сравни, затем открой объяснение ниже.</p>`)}<div class="preps"><div class="prep"><strong>AT</strong><p><b>Точка на часах</b><br>at 8:00<br>at half past four</p><p>И устойчивые сочетания:<br><b>at night</b><br><b>at the weekend</b> (BrE)</p></div><div class="prep"><strong>ON</strong><p><b>День или дата</b><br>on Monday<br>on 6 May<br>on my birthday</p><p>Конкретная часть конкретного дня:<br><b>on Monday morning</b></p></div><div class="prep"><strong>IN</strong><p><b>Большой отрезок</b><br>in January<br>in autumn<br>in 1992</p><p>Обычные части суток:<br><b>in the morning / afternoon / evening</b></p></div></div>${detail('Почему in May, но on 6 May?',`<p><b>In May</b> — когда-то в течение месяца. <b>On 6 May</b> — один конкретный день. Не выбирай предлог только по слову May: сначала проверь, есть ли число.</p><p class="example">My birthday is <b>in May</b>.<br>My birthday is <b>on the sixth of May</b>.</p>`)}${detail('Частые ловушки — разбираем спокойно',table(['Ошибка','Как правильно','Почему'],[['in Friday','on Friday','это день недели'],['on 8:00','at 8:00','это время на часах'],['at autumn','in autumn','это сезон'],['in 6 May','on 6 May','это конкретная дата'],['in night','at night','устойчивое сочетание'],['in Monday morning','on Monday morning','есть конкретный день']])+`<p>В американском английском часто <b>on the weekend</b>; в британском учебнике — <b>at the weekend</b>. Это разные варианты, а не «правильный и неправильный английский».</p><p><b>Today, tomorrow, yesterday, next week, last Monday, this evening</b> обычно обходятся без at/on/in: <b>See you tomorrow!</b>, <b>My birthday is next week.</b></p>`)}${detail('Найдём доказательства в приглашениях',`<p>A: <b>on Sat 15 Dec</b>, <b>at 17:30</b>. C: <b>at 8:00 pm</b>. D: <b>on Sunday, 4th September</b>, <b>at 5:45 pm</b>. В коротких карточках часть слов иногда опускают ради компактности.</p>`)}${keks('Сначала спроси себя: часы, день или большой период? Потом проверь исключения.')}`;
    if(id==='radio')return `<h2>Новое голосовое. Сначала — смысл.</h2><p>Это новый учебный диалог по темам 2a, не запись из учебника. Не открывай текст заранее. Предположи: какие три детали услышишь в приглашении?</p>${area('prediction','Моё предположение (можно по-русски)','Например: имя, дата…')}${note('Как слушать',`<ol><li>Первый раз: что за событие и кто кого приглашает?</li><li>Второй раз: запиши дату, время и адрес.</li><li>Открой игру и ответь. Текст станет доступен после попытки.</li></ol><p>Можно слушать голос браузера или попросить преподавателя прочитать сообщение из Tutor Notes. Качество голоса зависит от устройства. Основной урок работает и без озвучки.</p>`)}<div class="actions"><button class="primary" data-listen>▷ PLAY MESSAGE</button><button data-stop>STOP</button><button data-tab="play">ПЕРЕЙТИ К ВОПРОСАМ →</button></div>${transcript()}${area('listening-notes','Мои заметки: event / date / time / address')}`;
    if(id==='speaking')return `<h2>Не просто ответь. Узнай что-то новое.</h2>${table(['Реплика','Смысл'],[["Whose birthday is in spring?",'Чей день рождения весной?'],['Mine.','Мой.'],["When’s your birthday?",'Когда твой день рождения?'],["It’s on the fifth of May.",'Он 5 мая.'],['How old are you?','Сколько тебе лет?'],["I’m twelve.",'Мне 12 лет.']])}${note('Age: I AM, не I HAVE',`<p>По-английски возраст описываем с <b>am / is / are</b>: <b>I’m twelve</b>, а не I have twelve. Можно сказать <b>I’m twelve years old</b>. Вопрос об возрасте можно пропустить или использовать выдуманный возраст.</p>`)}${detail('Модель интервью — сначала прочитайте по ролям',`<p class="example">A: When’s your birthday?<br>B: It’s on the fifth of May.<br>A: So it’s in spring! How old are you?<br>B: I’m twelve. What about you?<br>A: Mine is on the twenty-first of August.</p><p><b>What about you?</b> — «А у тебя?» После ответа задаём свой вопрос. Имена и даты здесь выдуманы.</p>`)}${bridge('Назови свой или выдуманный день рождения. Добавь сезон.','Спроси преподавателя о дате, затем уточни: Is it in spring?')}<div class="actions"><button data-tab="play">ОТКРЫТЬ BIRTHDAY NETWORK →</button></div>`;
    if(id==='writing')return `<h2>Карточка должна помогать гостю.</h2><p>У хорошего приглашения есть <b>кому / на что / когда / где / от кого</b>. Сначала разберём готовую модель, потом напишем свою.</p><article class="invite"><div class="kicker">Model · выдуманный пример</div><p class="example" lang="en">Dear Alex,<br>You’re invited to my birthday party!<br>On Sat 21 Jun at 4:30 pm.<br>At 12 Park Rd.<br>Hope to see you there!<br>Mia</p></article>${table(['Часть','Фраза','Смысл'],[['Кому','Dear Alex,','Дорогой Алекс,'],['Событие',"You’re invited to my birthday party!",'Приглашаю на мой день рождения.'],['Дата','On Sat 21 Jun','В субботу, 21 июня.'],['Время','at 4:30 pm','в 16:30'],['Адрес','At 12 Park Rd.','по адресу 12 Park Road'],['Завершение','Hope to see you there!','Надеюсь увидеть тебя там!'],['Подпись','Mia','Кто приглашает']])}${detail('Как сократить письмо Клэр, сохранив смысл',`<p>В карточке не обязательно оставлять длинное вступление <b>My 12th birthday is next week</b>. Но событие, дату, время и адрес терять нельзя. Сокращаем:</p><p><b>Sunday → Sun</b>, <b>September → Sept</b>, <b>Road → Rd.</b> Возраст можно оставить в <b>my 12th birthday party</b>. Адрес Westbourne помогает понять место.</p><p>Помни: <b>5:45 pm = 17:45</b>. Если напишешь am, получится раннее утро.</p>`)}<div class="actions"><button data-tab="play">ПРЕВРАТИТЬ ПИСЬМО В КАРТОЧКУ →</button></div>`;
    if(id==='boss')return `<h2>Final case: wrong details, real trouble.</h2><p>Сотрудник бюро набрал приглашение с ошибками. Гость может прийти не в тот день или не в то время. Твоя задача — исправить дело.</p><article class="invite"><div class="kicker">Draft with mistakes · здесь есть ошибки</div><p class="example">Dear Tina,<br>You’re invited to my birthday party!<br>In Sat 15 Dec, on 17:30.<br>18 Oxbridge Rd., Plymton.<br>Janet</p></article>${note('План расследования',`<ol><li>Расшифруй сокращения.</li><li>Назови дату и время вслух.</li><li>Замени неверные предлоги.</li><li>Добавь дружелюбное завершение.</li><li>Попроси преподавателя уточнить одну деталь.</li></ol>`)}${bridge('Объясни по-русски, почему in Sat не подходит. Потом скажи исправленную фразу по-английски.','Tutor: притворитесь гостем. Переспросите: What time? In the morning or in the afternoon?')}`;
    return `<h2>Что ты уже можешь сделать?</h2><p>Здесь нет оценки за честный ответ. Выбери, что получается самостоятельно, а что хочется повторить. Затем пригласи преподавателя на выдуманную вечеринку без текста.</p>${note('Небольшая проверка без подсказок',`<p>Скажи: «Моя вечеринка 21 июня в 16:30. Приходи по адресу 12 Park Road». Если остановишься, открой нужный этап карты и повтори одну часть.</p>`)}<button data-tab="use">МОЙ EXIT TICKET →</button>`;
  }
  function dateExplorer(){const m=+state.date.m,d=+state.date.d;return `<div class="callout yellow"><div class="kicker">DATE BUILDER</div><div class="two"><label class="field">День<select data-date="d">${Array.from({length:31},(_,i)=>`<option value="${i+1}" ${d===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><label class="field">Месяц<select data-date="m">${D.months.map((x,i)=>`<option value="${i}" ${m===i?'selected':''}>${x[0]}</option>`).join('')}</select></label></div><div id="date-output">${dateOutput()}</div></div>`;}
  function dateOutput(){const {d,m}=state.date;return `<p class="example">${D.ordinal(d)} ${D.months[m][0]}<br>It’s <b>the ${D.ordinalWords[d-1]} of ${D.months[m][0]}</b>.</p><p class="small">${m===1&&d===29?'29 February — пример для високосного года. ':''} <b>Если это день рождения:</b> It’s <b>on</b> the ${D.ordinalWords[d-1]} of ${D.months[m][0]}.</p><button data-say="It’s the ${D.ordinalWords[d-1]} of ${D.months[m][0]}">▷ Прочитать дату</button>`;}
  const nums=['twelve','one','two','three','four','five','six','seven','eight','nine','ten','eleven'];
  const minuteWords={5:'five',10:'ten',15:'quarter',20:'twenty',25:'twenty-five',30:'half'};
  function timePhrase(h,m){const hour=nums[h%12];if(m===0)return `${hour} o’clock`;if(m<=30)return `${minuteWords[m]} past ${hour}`;return `${minuteWords[60-m]} to ${nums[(h+1)%12]}`;}
  function clock(h,m){return `<svg class="clock" viewBox="0 0 260 260" role="img" aria-label="Часы ${h}:${String(m).padStart(2,'0')}"><circle cx="130" cy="130" r="119" fill="#fff" stroke="#191919" stroke-width="4"/><path d="M130 11 A119 119 0 0 1 130 249" fill="none" stroke="#3D3BFF" stroke-width="7"/><path d="M130 249 A119 119 0 0 1 130 11" fill="none" stroke="#FF4FA3" stroke-width="7"/>${Array.from({length:12},(_,i)=>{const a=i*Math.PI/6;return `<text x="${130+96*Math.sin(a)}" y="${135-96*Math.cos(a)}" text-anchor="middle">${i||12}</text>`;}).join('')}<text x="171" y="135" text-anchor="middle" style="font-size:10px;fill:#3D3BFF">PAST</text><text x="86" y="135" text-anchor="middle" style="font-size:10px;fill:#972939">TO</text><line x1="130" y1="130" x2="130" y2="71" stroke="#191919" stroke-width="9" stroke-linecap="round" transform="rotate(${h%12*30+m*.5} 130 130)"/><line x1="130" y1="130" x2="130" y2="45" stroke="#3D3BFF" stroke-width="5" stroke-linecap="round" transform="rotate(${m*6} 130 130)"/><circle cx="130" cy="130" r="7" fill="#191919"/></svg>`;}
  function clockOutput(){const {h,m}=state.clock;return `${clock(h,m)}<div class="digital">${h}:${String(m).padStart(2,'0')}</div><div class="clock-caption" lang="en">It’s ${timePhrase(h,m)}.</div><p class="small">${m===0?'Целый час → o’clock.':m<=30?`${m} минут прошло после ${h}. Называем текущий час: ${nums[h%12]}.`:`60 − ${m} = ${60-m} минут осталось до ${h%12+1}. Называем следующий час: ${nums[(h+1)%12]}.`}</p>`;}
  function clockExplorer(){return `<div class="clock-layout"><div id="clock-output">${clockOutput()}</div><div class="clock-controls"><label>Час: <output id="hour-val">${state.clock.h}</output><input type="range" min="1" max="12" step="1" value="${state.clock.h}" data-clock="h" aria-label="Выбрать час"></label><label>Минуты: <output id="minute-val">${state.clock.m}</output><input type="range" min="0" max="55" step="5" value="${state.clock.m}" data-clock="m" aria-label="Выбрать минуты"></label><div class="actions"><button data-say-clock>▷ Listen</button><button data-clock-random>Случайное время</button></div><p class="small">Синяя половина: past. Розовая: to. На 30-й минуте используем half past.</p></div></div>`;}
  function quiz(id,items=D.quizzes[id]){const a=state.answers[id]||{},checks=state.checks[id]||{};return `<div class="quiz" data-quiz="${id}"><div class="kicker">CORE CHECK · ${items.length} заданий</div><h2>${id==='radio'?'Listen, then investigate.':'Проверь дело.'}</h2><p class="small">Введи ответы или выбери варианты. Затем нажми Check. Регистр и лишние пробелы не мешают проверке; дефис и пробел в twenty-first равнозначны.</p>${items.map((q,i)=>`<div class="q">${q.options?`<div class="q-title" id="prompt-${id}-${i}">${i+1}. ${esc(q.prompt)}</div>`:`<label for="answer-${id}-${i}">${i+1}. ${esc(q.prompt)}</label>`}${q.options?`<div class="options" role="group" aria-label="${esc(q.prompt)}">${q.options.map(x=>`<button data-choice="${id}|${i}|${esc(x)}" class="${a[i]===x?'selected':''}" aria-pressed="${a[i]===x}">${esc(x)}</button>`).join('')}</div>`:`<input id="answer-${id}-${i}" data-answer="${id}|${i}" value="${esc(a[i]||'')}" autocomplete="off" spellcheck="false" aria-label="${esc(q.prompt)}">`}<button class="quiet" data-hint="${id}|${i}">Need a Hint? · Подсказка</button>${state.hints[id+'|'+i]?`<div class="hint">${esc(q.hint)}</div>`:''}${checks[i]===true?`<div class="feedback" role="status">✓ Верно. ${esc(q.why)}</div>`:checks[i]===false?`<div class="feedback wrong" role="status">↻ Попробуй ещё. ${esc(q.hint)}${(state.tries[id+'|'+i]||0)>=2?`<br><button class="quiet" data-reveal="${id}|${i}">Показать ответ и объяснение</button>`:''}</div>`:''}${state.reveals[id+'|'+i]?`<div class="hint">Ответ: <b>${esc(q.answer[0])}</b>. ${esc(q.why)}<br>Теперь введи ответ самостоятельно и проверь ещё раз.</div>`:''}</div>`).join('')}<div class="actions"><button class="primary" data-check="${id}">CHECK · ПРОВЕРИТЬ</button><button data-retry="${id}">TRY AGAIN · СНАЧАЛА</button></div><div class="result" aria-live="polite">${Object.keys(checks).length?`${Object.values(checks).filter(Boolean).length} / ${items.length} верно. ${Object.values(checks).filter(Boolean).length===items.length?'✓ Дело закрыто!':'Исправь ошибки и проверь снова.'}`:''}</div></div>`;}
  function play(id){
    if(id==='days')return `<h2>Week repair / восстанови неделю</h2><p>Календарь перепутался. Двигай дни кнопками ↑ ↓. У скорости нет значения.</p>${orderGame('week',D.days.map(x=>x[0]))}${detail('Extra Practice · Memory Flip — день и перевод',memoryGame())}${quiz(id)}${detail('Extra Practice · вспомни все дни без списка',quiz('dayRecall'))}`;
    if(id==='months')return `<h2>Season sorter</h2><p>Нажми месяц, затем нужный сезон. Чтобы изменить выбор, нажми месяц внутри сезона. Кнопки работают мышью, касанием и клавиатурой.</p>${seasonGame()}${quiz(id)}${detail('Extra Practice · вспомни все 12 месяцев',quiz('monthRecall'))}`;
    if(id==='ordinals')return `<h2>Два режима фабрики</h2>${note('Карточка-инструкция',`<p>Сначала найди на этапе «Разберёмся» правило и примеры. Потом закрой таблицу и восстанови формы по памяти. Каждая форма пригодится для даты.</p>`)}${quiz(id)}${detail('Extra Practice · числа 21–31 и трудные формы',quiz('ordinalRecall'))}${detail('Extra Challenge · сочетаем число и существительное',`<p>Скажи вслух: 6-й класс; 1 июня; 21-й день рождения; 30 апреля. Преподаватель проверяет произношение.</p><button data-extra-model="ordinal-model">Показать модель после своей попытки</button>${state.open['ordinal-model']?'<p>the sixth form · the first of June · the twenty-first birthday · the thirtieth of April</p>':''}`)}`;
    if(id==='dates')return `<h2>Date decoder</h2><p>День / месяц: прочитай дату и напечатай порядковое числительное. Затем назови всю дату вслух.</p>${quiz(id)}${detail('Extra Practice · Yesterday desk',`<p>Назови вчерашнюю дату для каждого случая. Затем открой проверку.</p>${['17 August','3 June','1 January','2 December','29 October','12 May'].map((d,i)=>`<p>${d} → <button class="quiet" data-extra-model="y${i}">Проверить себя</button> ${state.open['y'+i]?['the sixteenth of August','the second of June','the thirty-first of December','the first of December','the twenty-eighth of October','the eleventh of May'][i]:''}</p>`).join('')}`)}`;
    if(id==='time')return `<h2>Clock lab / практика</h2><p>Все восемь времён со страницы учебника — в этой проверке. Можно отвечать способом past/to или цифровым способом.</p>${quiz(id)}${detail('Extra Practice · Clock mystery',clockMystery())}`;
    if(id==='preps')return `<h2>Three gates / выбери ворота</h2><p>Не торопись: определи, что перед тобой — время, день, дата, месяц или исключение.</p>${quiz(id)}${detail('Extra Practice · Random cue game — игра из учебника для 1:1',prepCue())}`;
    if(id==='radio')return `<h2>Слушай, отмечай, перепроверяй.</h2><div class="actions"><button class="primary" data-listen>▷ СЛУШАТЬ ЕЩЁ РАЗ</button><button data-stop>STOP</button></div>${quiz(id)}${transcript()}${detail('Extra Practice · восстанови порядок деталей',orderGame('message',['Greeting','Birthday invitation','Date','Time','Address','Games','Goodbye']))}`;
    if(id==='speaking')return birthdayNetwork();
    if(id==='writing')return `<h2>Claire’s email → invitation card</h2><p>Сохрани событие, воскресенье 4 сентября, 17:45 и адрес. Заполни карточку сокращениями. Это подготовка перед собственным приглашением.</p>${quiz('claire',claireQuiz())}<article class="invite"><p>Dear Sara,<br>You’re invited to my 12th birthday party!<br>On <b>${esc((state.answers.claire||{})[0]||'___')}</b> 4 <b>${esc((state.answers.claire||{})[1]||'___')}</b> at 5:45 pm.<br>At 17 Belgrave <b>${esc((state.answers.claire||{})[2]||'___')}</b>, Westbourne.<br>See you there!<br>Claire</p></article><button class="primary" data-tab="use">ТЕПЕРЬ МОЁ ПРИГЛАШЕНИЕ →</button>`;
    if(id==='reflect')return use(id);
    return `${id==='inbox'?'<p>Карточки всегда доступны во вкладке «Разберёмся». Найди конкретные слова-доказательства для каждого ответа.</p>':''}${quiz(id)}${id==='inbox'?detail('Extra Practice · invitation decoder',quiz('abbreviations')):''}`;
  }
  function claireQuiz(){return [D.q('Sunday → короткая форма','Sun','Первые три буквы.','Sun = Sunday.'),D.q('September → короткая форма',['Sept','Sep'],'Первые три или четыре буквы.','Sept / Sep = September.'),D.q('Road → короткая форма',['Rd','Rd.'],'Первая и последняя буквы.','Rd. = Road.')];}
  function orderGame(id,correct){let x=state.extra[id];if(!x){let arr=shuffle(correct);if(arr.every((v,i)=>v===correct[i]))arr.reverse();x=state.extra[id]={arr};save();}return `<div data-order="${id}"><ol class="order-list">${x.arr.map((v,i)=>`<li><span>${esc(v)}</span><button data-move="${id}|${i}|-1" ${i===0?'disabled':''} aria-label="${esc(v)} выше">↑</button><button data-move="${id}|${i}|1" ${i===x.arr.length-1?'disabled':''} aria-label="${esc(v)} ниже">↓</button></li>`).join('')}</ol><div class="actions"><button data-order-check="${id}">Check order</button><button data-extra-reset="${id}">Try again / перемешать</button></div>${x.feedback?`<div class="feedback ${x.ok?'':'wrong'}" role="status">${x.feedback}</div>`:''}</div>`;}
  function memoryGame(){let m=state.extra.memory;if(!m){m=state.extra.memory={deck:shuffle(D.days.slice(0,6).flatMap((d,i)=>[{id:i+'e',pair:i,text:d[0]},{id:i+'r',pair:i,text:d[1]}])),open:[],matched:[]};save();}return `<p>Найди 6 пар: английский день + русский перевод. Для несовпавшей пары нажми «Закрыть».</p><div class="memory-grid">${m.deck.map(c=>{const visible=m.open.includes(c.id)||m.matched.includes(c.pair);return `<button class="memory-card ${visible?'open':''} ${m.matched.includes(c.pair)?'matched':''}" data-memory="${c.id}" ${m.matched.includes(c.pair)?'disabled':''} aria-label="${visible?esc(c.text):'Закрытая карточка'}">${visible?esc(c.text):'?'}</button>`;}).join('')}</div>${m.open.length===2?'<button data-memory-close>Закрыть несовпавшую пару</button>':''}<p class="small">${m.matched.length} / 6 пар ${m.matched.length===6?'✓ Найдены все пары!':''}</p><button data-extra-reset="memory">Перемешать и начать снова</button>`;}
  function seasonGame(){const x=state.extra.seasons||(state.extra.seasons={positions:{},order:shuffle(D.months.map(m=>m[0]))});return `<div class="sort-bank">${x.order.filter(w=>!x.positions[w]).map(w=>`<button data-month-select="${w}" class="${x.selected===w?'selected':''}" aria-pressed="${x.selected===w}">${w}</button>`).join('')}</div><p class="small" aria-live="polite">${x.selected?'Выбрано: '+esc(x.selected)+'. Теперь нажми сезон.':'Выбери месяц.'}</p><div class="bins">${[['winter','Зима'],['spring','Весна'],['summer','Лето'],['autumn','Осень']].map(([s,ru])=>`<div class="bin"><button data-season="${s}">${s} · ${ru}</button>${Object.entries(x.positions).filter(([w,v])=>v===s).map(([w])=>`<button class="placed" data-month-select="${w}">${w} ↗</button>`).join('')}</div>`).join('')}</div><div class="actions"><button data-season-check>CHECK SEASONS</button><button data-extra-reset="seasons">Try again</button><button class="quiet" data-extra-model="seasons-hint">Need a Hint?</button></div>${state.open['seasons-hint']?'<p class="hint">Начни с December–January–February → winter; следующие три месяца → spring. Каждый сезон содержит три месяца.</p>':''}${x.feedback?`<div class="feedback ${x.ok?'':'wrong'}">${esc(x.feedback)}</div>`:''}`;}
  function clockMystery(){const x=state.extra.clockMystery||(state.extra.clockMystery={h:Math.ceil(Math.random()*12),m:Math.floor(Math.random()*12)*5});return `${clock(x.h,x.m)}${input('clockGuess','Введи время цифрами, например 3:45')}<div class="actions"><button data-clock-guess>CHECK</button><button data-extra-reset="clockMystery">Новые часы</button><button data-extra-model="clock-hint">Need a Hint?</button></div>${state.open['clock-hint']?'<p class="hint">Начни с короткой стрелки (часы), затем найди деление длинной стрелки и умножь его номер на 5.</p>':''}${x.feedback?`<p class="feedback ${x.ok?'':'wrong'}">${x.feedback}</p>`:''}`;}
  const cues=[['August','in','месяц'],['the weekend','at','устойчивое сочетание BrE'],['night','at','устойчивое сочетание'],['6 May','on','дата'],['2014','in','год'],['Friday','on','день'],['the morning','in','часть суток'],['8:00','at','время'],['autumn','in','сезон'],['Monday evening','on','конкретный день']];
  function prepCue(){const x=state.extra.cue||(state.extra.cue={order:shuffle(cues.map((_,i)=>i)),index:0,score:0});const c=cues[x.order[x.index%cues.length]];return `<div class="date-display">${c[0]}</div><p>Скажи сочетание вслух, затем выбери предлог. Верный ответ открывает следующую карточку. Раунд: ${x.index%cues.length+1} / 10.</p><div class="actions">${['at','on','in'].map(p=>`<button data-cue="${p}">${p.toUpperCase()}</button>`).join('')}</div>${x.feedback?`<p class="feedback ${x.ok?'':'wrong'}">${x.feedback}</p>`:''}${x.ok?'<button data-cue-next>Следующая карточка →</button>':''}<button class="quiet" data-extra-model="cue-hint">Need a Hint?</button>${state.open['cue-hint']?`<p class="hint">Здесь: ${c[2]}.</p>`:''}<p class="small">${x.score} верных карточек за эту сессию. Таймера нет.</p>`;}
  function transcript(){const attempted=Object.keys(state.checks.radio||{}).length>0;return attempted?detail('Transcript · открыть после своей попытки',`<p lang="en">${D.script}</p><p><b>on the twenty-first of June</b> — 21 июня; <b>at half past four in the afternoon</b> — в 16:30; <b>twelve Park Road</b> — 12 Park Road.</p>`):'<p class="small">Текст скрыт до попытки в Core Check. При недоступной озвучке преподаватель найдёт текст в Tutor Notes.</p>';}
  function birthdayNetwork(){return `<h2>Birthday network</h2><p>Задай вопросы преподавателю и запиши ответы. Затем добавь ещё 1–2 выдуманных гостей. Настоящий адрес и фамилия не нужны.</p><div class="two">${input('guestName','Имя гостя или персонажа')}${input('guestAge','Возраст (можно пропустить)')}</div><div class="two"><label class="field">День<select data-field="guestDay">${Array.from({length:31},(_,i)=>`<option ${Number(field('guestDay',5))===i+1?'selected':''}>${i+1}</option>`).join('')}</select></label><label class="field">Месяц<select data-field="guestMonth">${D.months.map((m,i)=>`<option value="${i}" ${Number(field('guestMonth',4))===i?'selected':''}>${m[0]}</option>`).join('')}</select></label></div><button class="primary" data-add-guest>ДОБАВИТЬ В КАЛЕНДАРЬ</button><div>${state.guests.map((g,i)=>`<div class="guest"><span><b>${esc(g.name)}</b> · ${D.ordinal(g.d)} ${D.months[g.m][0]}${g.age?' · '+esc(g.age)+' years old':''}<br><small>${esc(g.name)}’s birthday is on the ${D.ordinalWords[g.d-1]} of ${D.months[g.m][0]}.</small></span><button class="quiet" data-delete-guest="${i}" aria-label="Убрать ${esc(g.name)}">×</button></div>`).join('')}</div>${bridge('Посмотри на календарь. Whose birthday is in spring? Назови гостя и дату.','Преподаватель меняет одну деталь. Ученик замечает: No, it’s on… Потом поменяйтесь ролями.')}${detail('Extra Challenge · два гостя с одной датой',`<p>Добавь двух персонажей с одним днём рождения. Скажи: <b>Maria and Pete’s birthdays are on the fifth of May.</b> Для разных дат назови гостей отдельно.</p>`)}`;}
  function use(id){
    const turns={inbox:['Выбери одну карточку и сообщи преподавателю 4 детали: кто, событие, дата, время.','Which party would you like to go to? Why?'],days:['My favourite day is ___. I have ___ lessons on ___.','What’s your favourite day of the week? Why?'],months:['My birthday is in ___. It’s in ___. I like ___ because ___.','When is your birthday? Is it in winter, spring, summer or autumn?'],ordinals:['Назови 21-й, 22-й, 23-й и 30-й день. Затем: I’m in the sixth form.','Tutor: назовите 3 числительных, а ученик составит сочетания с birthday / form / of May.'],dates:["My birthday is on the ___ of ___. Today is the ___ of ___. Yesterday was the ___ of ___.",'What’s the date today? What was the date yesterday?'],time:['Представь, что на часах 8:10, 12:45 или 2:55. Ответь двумя способами.','Excuse me, what time is it, please? Затем поменяйтесь ролями.'],preps:['Закончи 3 предложения: My birthday is… / I have English… / I usually play games…','Назови время, день и месяц своей вечеринки. Преподаватель уточнит одну деталь.'],radio:['Передай приглашение Лео своими словами: Mia’s party is… / It starts… / The address is…','Would you like to go? What details would you ask about?'],boss:['Пригласи преподавателя. Назови событие, дату, время, адрес. Затем уточни его планы.','Tutor: запутайте только одну деталь. Ученик должен вежливо поправить и повторить её.']};
    if(id==='writing')return writingStudio();
    if(id==='reflect')return reflection();
    if(id==='speaking')return `${birthdayNetwork()}${area('interview','Мой мини-отчёт','My tutor’s birthday is on…')}${checkboxes('speak-ok-',['Я задал(а) вопрос о дате.','Я назвал(а) день рождения целой фразой.','Я задал(а) встречный вопрос.'])}<button data-open-complete="speaking">ПРОВЕРИЛИ С ПРЕПОДАВАТЕЛЕМ · ЗАВЕРШИТЬ</button>`;
    const [s,t]=turns[id];return `<h2>Теперь используй это для себя.</h2>${bridge(s,t)}${area(id+'-use','Заметки или свой пример','Можно сначала записать опору, потом сказать без неё.')}${detail('Need a Hint? · Опора для ответа',`<p>${id==='inbox'?'Janet is inviting Tina to a birthday party. It’s on the fifteenth of December at half past five.':id==='days'?'My favourite day is Friday. I have music lessons on Friday.':id==='months'?'My birthday is in May. It’s in spring.':id==='ordinals'?'the twenty-first birthday · the twenty-second day · the twenty-third of May · the thirtieth of April':id==='dates'?'It’s on the fifth of May. Today is the seventeenth of August. Yesterday was the sixteenth of August.':id==='time'?'It’s ten past eight. / It’s eight ten. Thank you!':id==='preps'?'My birthday is in May. My party is on the fifth of May at four o’clock.':id==='radio'?'Mia’s party is on the twenty-first of June at half past four in the afternoon. The address is twelve Park Road.':'Please come to my party on Saturday at half past five. Hope to see you there!'}</p>`)}${detail('Extra Challenge',`<p>Скажи первый ответ, глядя на опору. Затем закрой её и повтори, изменив одну деталь. Спроси преподавателя: <b>What about you?</b></p>`)}<p class="small">Это открытый ответ. Сайт сохраняет его, а преподаватель помогает улучшить смысл, грамматику и произношение.</p>`;
  }
  function writingStudio(){return `<h2>Your invitation / твоя вечеринка</h2><p>Выбери свою или выдуманную дату. Сначала собери опору, затем напиши целую карточку своим текстом.</p><div class="two">${input('inviteTo','Кому?','Alex')}${input('inviteFrom','От кого?','Mia')}${input('inviteDate','Дата (пиши по-английски)','Sat 21 Jun')}${input('inviteTime','Время','4:30 pm')}</div>${input('invitePlace','Выдуманный адрес','12 Park Rd.')}${area('inviteDraft','Моё приглашение (английский)','Dear…\nYou’re invited to…\nOn… at…\nAt…\nHope to see you there!\n…')}<div class="actions"><button data-build>ПОКАЗАТЬ КАРТОЧКУ ИЗ ПОЛЕЙ</button><button data-show-draft>ПОКАЗАТЬ МОЙ ТЕКСТ</button><button data-download>СКАЧАТЬ МОЙ ТЕКСТ .TXT</button></div><div id="invite-preview">${invitationPreview()}</div>${detail('Need a Hint? · Sentence starters',`<p>Dear… / You’re invited to my birthday party! / On… at… / My address is… / Hope to see you there! / подпись</p><p>Чтобы проверить сокращения, вернись к письму Клэр. Чтобы прочитать дату, открой Date desk.</p>`)}${checkboxes('write-ok-',['Есть обращение и подпись.','Понятно, что за событие.','Есть дата с on.','Есть время с at и понятным am/pm.','Есть место или выдуманный адрес.','Есть дружелюбное завершение.'])}${area('tutor-writing','Tutor feedback / одно удачное место и одно улучшение')}<button class="primary" data-open-complete="writing">ОБСУДИЛИ ПРИГЛАШЕНИЕ · ЗАВЕРШИТЬ</button><p class="small">Чек-лист — самопроверка, а не автоматическая оценка английского. Отправки приглашения другим людям здесь нет.</p>`;}
  function builtInvitation(){return `Dear ${field('inviteTo','Alex')},\nYou’re invited to my birthday party!\nOn ${field('inviteDate','Sat 21 Jun')} at ${field('inviteTime','4:30 pm')}.\nAt ${field('invitePlace','12 Park Rd.')}.\nHope to see you there!\n${field('inviteFrom','Mia')}`.replace(/\.\./g,'.');}
  function invitationPreview(){if(!state.fields.previewMode)return '';return `<div class="preview" lang="en">${esc(state.fields.previewMode==='draft'?field('inviteDraft'):builtInvitation())}</div><p class="small">${state.fields.previewMode==='draft'?'Показан твой текст.':'Показана опора из полей. Проверь её вместе с преподавателем; затем напиши собственный вариант.'}</p>`;}
  function reflection(){const labels=['Я понимаю, кто кого приглашает.','Я могу назвать день недели.','Я могу назвать месяцы и сезоны.','Я различаю one и first.','Я могу сказать дату рождения.','Я могу спросить, который час.','Я понимаю quarter / half / past / to.','Я выбираю at / on / in.','Я могу узнать дату в голосовом сообщении.','Я могу написать понятное приглашение.'];return `<h2>10 маленьких can-do.</h2><p>Для каждого навыка выбери честный ответ. Можно менять его после повторения.</p>${labels.map((x,i)=>`<div class="q"><b>${i+1}. ${x}</b><div class="reflections">${[['solo','Самостоятельно'],['help','С подсказкой'],['again','Хочу повторить']].map(([v,label])=>`<button data-reflect="${i}|${v}" class="${field('reflect'+i)===v?'selected':''}" aria-pressed="${field('reflect'+i)===v}">${label}</button>`).join('')}</div></div>`).join('')}${area('nextGoal','Один шаг на следующий урок','Я повторю…')}${area('exit-message','Exit ticket: моё приглашение без опоры','Please come to…')}<button class="primary" data-open-complete="reflect">СОХРАНИТЬ EXIT TICKET · ЗАВЕРШИТЬ</button>`;}
  function teacherView(){return `<h2 id="dialog-title">Tutor notes</h2><p><b>Уровень:</b> A1 с поддержкой → A2; 11–12 лет. Формат: один ученик и преподаватель. Материал двух страниц 2a распределён на 3 занятия по 45–60 минут; при пробелах используйте 4–5 встреч.</p><p><b>Цель:</b> ученик понимает приглашение, спрашивает и сообщает дату/время, выбирает предлоги и создаёт собственную карточку с понятными деталями.</p><p><b>Core:</b> контекст и короткие пояснения Learn → основной Core Check → 1 личный ответ Use. Дополнительные игры в раскрывающихся блоках можно пропустить. Не пытайтесь пройти все пояснения и Extra Practice за одну встречу.</p><p><b>Мягкая коррекция:</b> сначала смысл, затем одна форма. Для speaking/writing сайт не выставляет «верно» по ключевым словам: обсудите результат и отметьте этап вручную.</p>${detail('Listening fallback · прочитать ученику, не показывая экран',`<p>Учебный монолог, около 25–35 секунд. Прочитайте дважды с естественными паузами. Первый раз — gist, второй — детали.</p><p lang="en">${D.script}</p><p>Ключ: birthday party; Mia; 21 June; 4:30 pm; 12 Park Road; age — Not mentioned; winter — False.</p>`)}${detail('Слабый ученик: как дать поддержку',`<ol><li>Сначала проговорите один пример вместе.</li><li>Ученик выбирает значение, затем печатает без списка.</li><li>При ошибке спросите: «Какой это тип времени?» или «Сколько минут осталось до часа?»</li><li>Откройте hint. После двух неудачных проверок доступен разбор ответа.</li><li>Попросите сказать новый пример, чтобы ответ не остался копированием.</li></ol>`)}${detail('Ключи всех закрытых заданий',D.stages.filter(s=>s.quiz).map(s=>`<h3>${s.title}</h3><ol>${D.quizzes[s.quiz].map(q=>`<li>${esc(q.prompt)} → <b>${esc(q.answer.join(' / '))}</b></li>`).join('')}</ol>`).join(''))}${area('privateTutorNote','Заметки преподавателя · сохраняются на этом устройстве')}<p class="small">Reset All очищает все четыре хранилища этого курса, включая Module 1 и дополнительные тренажёры. Для повторения одного теста используйте Try again внутри задания.</p>`;}
  function resetView(){return `<h2 id="dialog-title">Новый ученик?</h2><p>Очистятся ответы, приглашения, календарь, заметки, подсказки и прогресс <b>Modules 1 и 2a</b> в этом браузере. Следующий ученик начнёт с чистого листа.</p><div class="actions"><button class="primary" data-confirm-reset>ОЧИСТИТЬ КУРС</button><button data-close>ОТМЕНА</button></div>`;}
  function bind(){
    root.querySelectorAll('details[data-detail]').forEach(el=>el.ontoggle=()=>{const key='detail:'+el.dataset.detail;if(!!state.open[key]!==el.open){state.open[key]=el.open;save();}});
    root.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>go(null));
    root.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
    root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{stop();state.tab=b.dataset.tab;save();render();});
    root.querySelector('[data-prev]')?.addEventListener('click',()=>go(D.stages[D.stages.findIndex(s=>s.id===state.stage)-1]?.id||null));
    root.querySelector('[data-next]')?.addEventListener('click',()=>go(D.stages[D.stages.findIndex(s=>s.id===state.stage)+1]?.id||null));
    root.querySelector('[data-teacher]').onclick=()=>{lastFocus=document.activeElement;teacher=true;resetModal=false;render();};
    root.querySelector('[data-reset]').onclick=()=>{lastFocus=document.activeElement;resetModal=true;teacher=false;render();};
    root.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);
    root.querySelector('[data-confirm-reset]')?.addEventListener('click',()=>{stop();clearTimeout(memTimer);clearTimeout(toastTimer);document.querySelector('.toast')?.remove();KEYS.forEach(k=>{try{localStorage.removeItem(k);}catch{}});state=fresh();teacher=false;resetModal=false;render();window.scrollTo(0,0);toast('Новый ученик: курс очищен.');});
    root.querySelectorAll('[data-field]').forEach(el=>{const handler=()=>{state.fields[el.dataset.field]=el.type==='checkbox'?el.checked:el.value;save();if(el.dataset.field.startsWith('invite')){const p=root.querySelector('#invite-preview');if(p)p.innerHTML=invitationPreview();}};el.addEventListener(el.tagName==='SELECT'||el.type==='checkbox'?'change':'input',handler);});
    root.querySelectorAll('[data-flash]').forEach(b=>b.onclick=()=>{state.open[b.dataset.flash]=!state.open[b.dataset.flash];save();render();});
    root.querySelectorAll('[data-say]').forEach(b=>b.onclick=()=>speak(b.dataset.say));
    root.querySelectorAll('[data-listen]').forEach(b=>b.onclick=()=>speak(D.script));
    root.querySelectorAll('[data-stop]').forEach(b=>b.onclick=stop);
    root.querySelectorAll('[data-extra-model]').forEach(b=>b.onclick=()=>{state.open[b.dataset.extraModel]=!state.open[b.dataset.extraModel];save();render();});
    root.querySelectorAll('[data-answer]').forEach(el=>el.oninput=()=>{const[id,i]=el.dataset.answer.split('|');state.answers[id]??={};state.answers[id][i]=el.value;if(state.checks[id])delete state.checks[id][i];if(id!=='claire')delete state.done[id];save();const f=el.closest('.q').querySelector('.feedback');f?.remove();const status=el.closest('.quiz').querySelector('.result');if(status)status.textContent='Ответ изменён. Нажми Check для новой проверки.';const bar=root.querySelector('[role=progressbar]');bar?.setAttribute('aria-valuenow',completed());if(bar)bar.querySelector('i').style.width=completed()/12*100+'%';});
    root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{const[id,i,v]=b.dataset.choice.split('|');state.answers[id]??={};state.answers[id][i]=v;if(state.checks[id])delete state.checks[id][i];delete state.done[id];save();render();});
    root.querySelectorAll('[data-hint]').forEach(b=>b.onclick=()=>{state.hints[b.dataset.hint]=!state.hints[b.dataset.hint];save();render();});
    root.querySelectorAll('[data-reveal]').forEach(b=>b.onclick=()=>{state.reveals[b.dataset.reveal]=true;save();render();});
    root.querySelectorAll('[data-check]').forEach(b=>b.onclick=()=>checkQuiz(b.dataset.check));
    root.querySelectorAll('[data-retry]').forEach(b=>b.onclick=()=>{const id=b.dataset.retry;delete state.answers[id];delete state.checks[id];delete state.done[id];for(const name of ['tries','hints','reveals'])Object.keys(state[name]).filter(k=>k.startsWith(id+'|')).forEach(k=>delete state[name][k]);save();render();});
    root.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{const[id,ix,ds]=b.dataset.move.split('|'),i=+ix,j=i+(+ds),x=state.extra[id];[x.arr[i],x.arr[j]]=[x.arr[j],x.arr[i]];delete x.feedback;save();render();});
    root.querySelectorAll('[data-order-check]').forEach(b=>b.onclick=()=>{const id=b.dataset.orderCheck,x=state.extra[id],correct=id==='week'?D.days.map(d=>d[0]):['Greeting','Birthday invitation','Date','Time','Address','Games','Goodbye'];x.ok=x.arr.every((v,i)=>v===correct[i]);x.feedback=x.ok?'✓ Порядок восстановлен. Теперь назови его без экрана.':'↻ Проверь последовательность. '+(id==='week'?'Начни с Monday; Sunday завершает неделю.':'Сначала приветствие, затем событие и его детали; прощание в конце.');save();render();});
    root.querySelectorAll('[data-extra-reset]').forEach(b=>b.onclick=()=>{const id=b.dataset.extraReset;delete state.extra[id];if(id==='clockMystery'){delete state.fields.clockGuess;delete state.open['clock-hint'];}save();render();});
    root.querySelectorAll('[data-memory]').forEach(b=>b.onclick=()=>{const m=state.extra.memory,id=b.dataset.memory;if(m.open.length>=2||m.open.includes(id))return;m.open.push(id);if(m.open.length===2){const cards=m.open.map(x=>m.deck.find(c=>c.id===x));if(cards[0].pair===cards[1].pair){m.matched.push(cards[0].pair);m.open=[];toast('✓ Пара найдена.');}}save();render();});
    root.querySelector('[data-memory-close]')?.addEventListener('click',()=>{state.extra.memory.open=[];save();render();});
    root.querySelectorAll('[data-month-select]').forEach(b=>b.onclick=()=>{state.extra.seasons.selected=b.dataset.monthSelect;save();render();});
    root.querySelectorAll('[data-season]').forEach(b=>b.onclick=()=>{const x=state.extra.seasons;if(!x.selected){toast('Сначала выбери месяц.');return;}x.positions[x.selected]=b.dataset.season;x.selected=null;delete x.feedback;save();render();});
    root.querySelector('[data-season-check]')?.addEventListener('click',()=>{const x=state.extra.seasons;const bad=D.months.filter(m=>x.positions[m[0]]!==m[3]);x.ok=bad.length===0;x.feedback=x.ok?'✓ Все 12 месяцев на своих местах.':'↻ Проверь: '+bad.map(m=>m[0]).join(', ')+'. Если месяц ещё в банке — сначала размести его.';save();render();});
    root.querySelectorAll('[data-clock]').forEach(el=>el.oninput=()=>{state.clock[el.dataset.clock]=+el.value;save();root.querySelector('#clock-output').innerHTML=clockOutput();root.querySelector('#hour-val').textContent=state.clock.h;root.querySelector('#minute-val').textContent=state.clock.m;});
    root.querySelector('[data-say-clock]')?.addEventListener('click',()=>speak('It’s '+timePhrase(state.clock.h,state.clock.m)));
    root.querySelector('[data-clock-random]')?.addEventListener('click',()=>{state.clock={h:Math.ceil(Math.random()*12),m:Math.floor(Math.random()*12)*5};save();render();});
    root.querySelectorAll('[data-date]').forEach(el=>el.onchange=()=>{state.date[el.dataset.date]=+el.value;const max=[31,29,31,30,31,30,31,31,30,31,30,31][state.date.m];if(state.date.d>max){state.date.d=max;toast('В этом месяце меньше дней. Число скорректировано.');}save();render();});
    root.querySelector('[data-clock-guess]')?.addEventListener('click',()=>{const x=state.extra.clockMystery;const v=String(field('clockGuess')).trim().replace('.',':').split(':').map(Number);x.ok=v[0]===x.h&&v[1]===x.m;x.feedback=x.ok?'✓ Да! '+timePhrase(x.h,x.m):'↻ Короткая стрелка — часы, длинная — минуты. На делении 7 будет 35 минут.';save();render();});
    root.querySelectorAll('[data-cue]').forEach(b=>b.onclick=()=>{const x=state.extra.cue,c=cues[x.order[x.index%cues.length]];if(x.ok)return;x.ok=b.dataset.cue===c[1];if(x.ok)x.score++;x.feedback=x.ok?'✓ '+c[1]+' '+c[0]+'. Это '+c[2]+'.':'↻ Здесь '+c[2]+'. Проверь правило и попробуй снова.';save();render();});
    root.querySelector('[data-cue-next]')?.addEventListener('click',()=>{const x=state.extra.cue;x.index++;x.ok=false;delete x.feedback;delete state.open['cue-hint'];if(x.index%10===0){x.order=shuffle(cues.map((_,i)=>i));toast('Раунд завершён. Начинается новый набор.');}save();render();});
    root.querySelector('[data-add-guest]')?.addEventListener('click',addGuest);
    root.querySelectorAll('[data-delete-guest]').forEach(b=>b.onclick=()=>{state.guests.splice(+b.dataset.deleteGuest,1);save();render();});
    root.querySelector('[data-build]')?.addEventListener('click',()=>{state.fields.previewMode='build';save();render();});
    root.querySelector('[data-show-draft]')?.addEventListener('click',()=>{if(!String(field('inviteDraft')).trim()){toast('Сначала напиши свой текст.');return;}state.fields.previewMode='draft';save();render();});
    root.querySelector('[data-download]')?.addEventListener('click',()=>{const t=String(field('inviteDraft')).trim();if(!t){toast('Сначала напиши свой текст приглашения.');return;}const url=URL.createObjectURL(new Blob([t],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='my-party-invitation.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
    root.querySelectorAll('[data-reflect]').forEach(b=>b.onclick=()=>{const[i,v]=b.dataset.reflect.split('|');state.fields['reflect'+i]=v;save();render();});
    root.querySelectorAll('[data-open-complete]').forEach(b=>b.onclick=()=>completeOpen(b.dataset.openComplete));
  }
  function checkQuiz(id){const qs=id==='claire'?claireQuiz():D.quizzes[id],a=state.answers[id]||{};if(qs.some((q,i)=>!String(a[i]||'').trim())){toast('Сначала ответь на каждый вопрос. Можно использовать подсказки.');return;}const c={};qs.forEach((q,i)=>{c[i]=q.answer.some(x=>norm(x)===norm(a[i]));if(!c[i])state.tries[id+'|'+i]=(state.tries[id+'|'+i]||0)+1;});state.checks[id]=c;if(D.stages.some(s=>s.id===id))state.done[id]=Object.values(c).every(Boolean);save();render();toast(Object.values(c).every(Boolean)?'✓ Всё верно. Используй это в своей фразе.':'Ответы проверены. Под каждым ответом — подсказка.');}
  function addGuest(){const name=String(field('guestName')).trim(),d=+field('guestDay',5),m=+field('guestMonth',4);if(!name){toast('Добавь имя персонажа или гостя.');return;}const max=[31,29,31,30,31,30,31,31,30,31,30,31][m];if(d>max){toast('В этом месяце нет такого числа. Выбери существующую дату.');return;}state.guests.push({name,d,m,age:field('guestAge')});state.fields.guestName='';state.fields.guestAge='';save();render();}
  function completeOpen(id){if(id==='speaking'&&(![0,1,2].every(i=>field('speak-ok-'+i))||!state.guests.length)){toast('Добавь гостя и обсуди три пункта чек-листа.');return;}if(id==='writing'&&(![0,1,2,3,4,5].every(i=>field('write-ok-'+i))||!String(field('inviteDraft')).trim())){toast('Напиши свой текст и пройди чек-лист с преподавателем.');return;}if(id==='reflect'&&(!Array.from({length:10},(_,i)=>field('reflect'+i)).every(Boolean)||!String(field('exit-message')).trim())){toast('Выбери ответ для 10 навыков и напиши exit ticket.');return;}state.done[id]=true;save();render();toast('✓ Этап отмечен после обсуждения с преподавателем.');}
  function closeModal(){teacher=false;resetModal=false;const what=lastFocus?.hasAttribute('data-reset')?'[data-reset]':'[data-teacher]';render();root.querySelector(what)?.focus();}
  document.addEventListener('keydown',e=>{if(!teacher&&!resetModal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const f=[...root.querySelector('.dialog').querySelectorAll('button,input,textarea,select,summary,a[href]')].filter(x=>!x.disabled&&(!x.closest('details')||x.tagName==='SUMMARY'||x.closest('details').open));const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  window.addEventListener('pagehide',stop);
  render();
})();
